@import url('https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap');

:root {
  --text-primary: #242424;
  --text-secondary: #424242;
  --background: #FFFFFF;
  --surface: #FAFAFA;
  --border: #D1D1D1;
}

body {
  display: flex;
  flex-direction: column;
  margin: 0;
  height: 100vh;
  font-family: "Segoe UI Variable", "Segoe UI", sans-serif;
}

nav > ul {
  display: flex;
  flex-wrap: wrap;
  list-style: none;
}

nav > ul > li {
  flex: 1 1 auto;
  text-align: center;
}

main {
  display: flex;
  flex: 1;
  justify-content: center;
  align-items: center;
}

main > section:not(:target) {
  display: none;
}

time {
  background: lightgrey;
  padding: 20px;
  border-radius: 8px;
  font-size: 8rem;
  text-align: center;
  margin: auto 0;
  color: var(--text-primary);
}

#alarm, #clock, #stopwatch, #timer {
  background: blue;
}

export default class Stopwatch extends HTMLElement {
  #intervalCallback;
  #intervalId = 0;

  constructor() {
    super();
    this.addEventListener("click", this);
    this.#intervalCallback = () => {
      const time = this.querySelector("time");
      const ms = new Date() - new Date(this.startTime);
      time.dateTime = `PT${ms / 1000}S`;
      time.textContent = new Date(ms).toISOString().slice(11, 22);
    };
  }

  static get observedAttributes() {
    return ["paused", "start-time"];
  }

  get paused() {
    return this.hasAttribute("paused");
  }

  set paused(value) {
    this.toggleAttribute("paused", Boolean(value));
  }

  get startTime() {
    return this.getAttribute("start-time");
  }

  set startTime(value) {
    this.setAttribute("start-time", value);
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) {
      return;
    }

    if (
      (name === "paused" && newValue != null) ||
      (name === "start-time" && !newValue)
    ) {
      clearInterval(this.#intervalId);
      this.#intervalId = 0;
    } else if (name === "start-time" && newValue && !this.#intervalId) {
      this.#intervalId = setInterval(this.#intervalCallback, 10);
    }
  }

  connectedCallback() {
    if (!this.paused && this.startTime && !this.#intervalId) {
      this.#intervalId = setInterval(this.#intervalCallback, 10);
    }
  }

  disconnectedCallback() {
    clearInterval(this.#intervalId);
  }

  handleEvent(event) {
    const { classList } = event.target;
    if (classList.contains("pause")) {
      this.pause();
    } else if (classList.contains("restart")) {
      this.restart();
    } else if (classList.contains("start")) {
      this.start();
    }
  }

  pause() {
    this.paused = true;
  }

  restart() {
    const time = this.querySelector("time");
    time.dateTime = "PT0S";
    time.textContent = "00:00:00.00";
    this.paused = false;
    this.startTime = "";
  }

  start() {
    const time = this.querySelector("time");
    time.dateTime = time.dateTime || "PT0S";
    this.paused = false;
    this.startTime = new Date(
      this.startTime
        ? new Date() - time.dateTime.match(/(\d+(:?\.\d+)?)S$/)[1] * 1000
        : new Date(),
    ).toISOString();
  }
}

import Alarm from "./Alarm.js";
import Clock from "./Clock.js";
import Stopwatch from "./Stopwatch.js";
import Timer from "./Timer.js";

customElements.define("x-alarm", Alarm);
customElements.define("x-clock", Clock);
customElements.define("x-stopwatch", Stopwatch);
customElements.define("x-timer", Timer);

export default class Clock extends HTMLElement {
  #intervalCallback;
  #intervalId = 0;

  constructor() {
    super();
    this.#intervalCallback = () => {
      const time = this.querySelector("time");
      const date = new Date();
      time.dateTime = date.toISOString();
      time.textContent = date.toLocaleTimeString();
    };
  }

  connectedCallback() {
    if (!this.#intervalId) {
      this.#intervalCallback();
      this.#intervalId = setInterval(this.#intervalCallback, 1000);
    }
  }

  disconnectedCallback() {
    clearInterval(this.#intervalId);
  }
}

export default class Alarm extends HTMLElement {
  #intervalCallback;
  #intervalId = 0;

  constructor() {
    super();
    this.addEventListener("click", this);
    this.duration = 60 * 1000;
    this.#intervalCallback = () => {
      this.alarms.forEach((alarm) => {
        const { value } = alarm.querySelector("input");
        const date =
          new Date(value).getTime() ||
          new Date(`${new Date().toLocaleDateString()} ${value}`).getTime();
        if (date) {
          const delta = Date.now() - date;
          if (delta > 0 && delta < new Date(this.duration)) {
            alarm.setAttribute("ringing", "");
            this.dispatchEvent(
              new CustomEvent("ring", { bubbles: true, detail: alarm })
            );
            return;
          }
        }

        alarm.removeAttribute("ringing");
      });
    };
  }

  get alarms() {
    return [...this.querySelector(".items").children];
  }

  get duration() {
    return Number(this.getAttribute("duration"));
  }

  set duration(value) {
    this.setAttribute("duration", value);
  }

  add() {
    const alarm = this.querySelector("template").content.cloneNode(true);
    this.querySelector(".items").appendChild(alarm);
  }

  connectedCallback() {
    if (!this.#intervalId) {
      this.#intervalId = setInterval(this.#intervalCallback, 1000);
    }
  }

  delete(alarm) {
    this.querySelector(".items").removeChild(alarm);
  }

  disconnectedCallback() {
    clearInterval(this.#intervalId);
  }

  handleEvent(event) {
    const { target } = event;
    const { classList } = target;
    if (classList.contains("add")) {
      this.add();
    } else if (classList.contains("delete")) {
      this.delete(this.alarms.find((alarm) => alarm.contains(target)));
    } else if (classList.contains("pause")) {
      this.pause(this.alarms.find((alarm) => alarm.contains(target)));
    } else if (classList.contains("start")) {
      this.start(this.alarms.find((alarm) => alarm.contains(target)));
    }
  }

  pause(alarm) {
    if (this.alarms.includes(alarm)) {
      alarm.setAttribute("paused", "");
    }
  }

  start(alarm) {
    if (this.alarms.includes(alarm)) {
      alarm.removeAttribute("paused");
    }
  }
}

export default class Timer extends HTMLElement {
  #intervalCallback;
  #intervalId = 0;

  constructor() {
    super();
    this.addEventListener("click", this);
    this.#intervalCallback = () => {
      const time = this.querySelector("time");
      const inputs = this.querySelectorAll("input");
      const intervals = Array.from(inputs, ({ value }) =>
        new Date(`1970-01-01T${value}Z`).getTime(),
      );
      const total = intervals.reduce((a, b) => a + b, 0);
      let ms;
      let remaining = new Date(new Date() - new Date(this.startTime)).getTime();
      if (remaining < total || this.loop) {
        remaining %= total;
        let i = 0;
        while (i < intervals.length && remaining > intervals[i]) {
          remaining -= intervals[i];
          i += 1;
        }

        ms = intervals[i] - remaining;
        inputs.forEach((input, j) => {
          input.classList.toggle("current-interval", i === j);
        });
      } else {
        clearInterval(this.#intervalId);
        this.#intervalId = 0;
        ms = 0;
        inputs.forEach((input) => {
          input.classList.remove("current-interval");
        });
        this.dispatchEvent(new CustomEvent("stop", { bubbles: true }));
      }

      time.dateTime = `PT${ms / 1000}S`;
      time.textContent = new Date(ms).toISOString().slice(11, 22);
    };
  }

  static get observedAttributes() {
    return ["paused", "start-time"];
  }

  get loop() {
    return this.hasAttribute("loop");
  }

  set loop(value) {
    this.toggleAttribute("loop", Boolean(value));
  }

  get paused() {
    return this.hasAttribute("paused");
  }

  set paused(value) {
    this.toggleAttribute("paused", Boolean(value));
  }

  get startTime() {
    return this.getAttribute("start-time");
  }

  set startTime(value) {
    this.setAttribute("start-time", value);
  }

  attributeChangedCallback(name, oldValue, newValue) {
    if (oldValue === newValue) {
      return;
    }

    if (
      (name === "paused" && newValue != null) ||
      (name === "start-time" && !newValue)
    ) {
      clearInterval(this.#intervalId);
      this.#intervalId = 0;
    } else if (name === "start-time" && newValue && !this.#intervalId) {
      this.#intervalId = setInterval(this.#intervalCallback, 10);
    }
  }

  disconnectedCallback() {
    clearInterval(this.#intervalId);
  }

  handleEvent(event) {
    const { classList } = event.target;
    if (classList.contains("loop")) {
      this.loop = true;
    } else if (classList.contains("no-loop")) {
      this.loop = false;
    } else if (classList.contains("pause")) {
      this.pause();
    } else if (classList.contains("restart")) {
      this.restart();
    } else if (classList.contains("start")) {
      this.start();
    }
  }

  pause() {
    this.paused = true;
  }

  restart() {
    const time = this.querySelector("time");
    time.dateTime = "PT0S";
    time.textContent = "00:00:00.00";
    this.paused = false;
    this.startTime = "";
  }

  start() {
    const time = this.querySelector("time");
    time.dateTime = time.dateTime || "PT0S";
    this.paused = false;
    if (this.startTime) {
      const inputs = this.querySelectorAll("input");
      const currentInput = this.querySelector(".current-interval");
      const intervals = Array.from(inputs, ({ value }) =>
        new Date(`1970-01-01T${value}Z`).getTime(),
      );
      const cumulativeTime = intervals
        .slice(0, [...inputs].indexOf(currentInput) + 1)
        .reduce((a, b) => a + b, 0);
      const ms = time.dateTime.match(/(\d+(:?\.\d+)?)S$/)[1] * 1000;
      this.startTime = new Date(new Date() - cumulativeTime + ms).toISOString();
    } else {
      this.startTime = new Date().toISOString();
    }
  }
}
